def _ua_lock3_connect(*a, **kw):
    if len(a) < 2 and "timeout" not in kw:
        kw["timeout"] = 30.0
    con = _ua_lock3_original_connect(*a, **kw)
    try:
        con.execute("PRAGMA busy_timeout=30000")
    except Exception:
        pass
    return con

def connect():
    vzyata = ZAMOK.acquire(timeout=ZAMOK_OZHIDANIE)
    try:
        conn = sqlite3.connect(DB_FILE, timeout=OZHIDANIE_SEK, factory=Soedinenie)
    except Exception:
        if vzyata:
            try:
                ZAMOK.release()
            except Exception:
                pass
        raise
    conn._ochered_vzyata = vzyata
    conn.row_factory = sqlite3.Row
    # WAL на сетевом диске PythonAnywhere ломает блокировки - только DELETE
    try:
        conn.execute("PRAGMA journal_mode=DELETE")
    except Exception:
        pass
    try:
        conn.execute("PRAGMA busy_timeout=%d" % (OZHIDANIE_SEK * 1000))
    except Exception:
        pass
    conn.execute("PRAGMA foreign_keys=ON")
    return conn

